// Aggregate rows by lead_email, keep most recent state per lead
const rows = $input.all().map(i => i.json);
if (rows.length === 0) return [{ json: { _no_leads: true } }];

// Group by lead_email: keep row with highest touch_sent (latest state)
const latest = {};
for (const row of rows) {
  const email = (row.lead_email || '').trim();
  if (!email) continue;
  const existing = latest[email];
  if (!existing) { latest[email] = row; continue; }
  const existingTouch = parseInt(existing.touch_sent) || 0;
  const thisTouch = parseInt(row.touch_sent) || 0;
  if (thisTouch > existingTouch) { latest[email] = row; continue; }
  if (thisTouch === existingTouch && (row.sent_at || '') > (existing.sent_at || '')) {
    latest[email] = row;
  }
}

// Filter: status=active AND next_send_at <= now AND touch_sent < 5
const now = new Date();
const due = Object.values(latest).filter(row => {
  if ((row.status_after || 'active') !== 'active') return false;
  if (parseInt(row.touch_sent) >= 5) return false;
  const nextSend = row.next_send_at ? new Date(row.next_send_at) : new Date(0);
  return nextSend <= now;
});

if (due.length === 0) return [{ json: { _no_leads: true, total_active: Object.values(latest).filter(r => r.status_after === 'active').length } }];

console.log('Due for next touch:', due.length, 'leads');
return due.map(lead => ({ json: lead }));

const lead = $input.first().json;
const config = $('Config').first().json;
const currentTouch = (parseInt(lead.touch_sent) || 0) + 1;

// ── ROLE DETECTION ──────────────────────────────────────────
function detectRole(t) {
  t = (t || '').toLowerCase();
  if (/ceo|presidente|fundador|founder|gerente general/.test(t)) return 'ceo';
  if (/cto|director.*(tecnolog|ti)|head of tech|vp.*engineer/.test(t)) return 'cto';
  if (/director.*ventas|vp.*(of )?sales|head of sales|chief revenue|cro/.test(t)) return 'sales_dir';
  if (/gerente.*ventas|sales manager|jefe.*ventas/.test(t)) return 'sales_mgr';
  if (/business dev|desarrollo.*negocio|growth/.test(t)) return 'bizdev';
  if (/transform.*digital|innovac|digitaliz/.test(t)) return 'digital';
  return '_default';
}

// ── INDUSTRY LOOKUP ──────────────────────────────────────────
function lookupIndustry(ind) {
  ind = (ind || '').toLowerCase();
  if (/information technology|software|tech|saas|it /.test(ind)) {
    return { hook: 'que tu equipo de ventas deje de perder tiempo buscando leads y se enfoque en cerrar', pain: 'en tech el ciclo de venta es largo y la mayoria de los leads nunca responden', metric: 'puedes hacer hasta cinco a siete veces mas conversiones que si intentaras armarlo tu mismo', question: 'de todos los leads que les llegan, cuantos realmente terminan respondiendo?' };
  }
  if (/financial|fintech|banco|segur|insurance/.test(ind)) {
    return { hook: 'automatizar la prospeccion sin que compliance sea un problema', pain: 'en finanzas la regulacion frena la adopcion de herramientas nuevas, pero eso no significa que tu equipo tenga que seguir prospectando a mano', metric: 'las empresas que usan todos los canales retienen casi el noventa por ciento de sus clientes, contra un tercio de las que usan un solo canal', question: 'cuando les llega un lead, tu equipo lo esta contactando en menos de cinco minutos?' };
  }
  if (/consult|servicio|professional service/.test(ind)) {
    return { hook: 'generar mas reuniones con prospectos calificados sin tener que contratar un equipo de prospeccion', pain: 'las consultoras necesitan un flujo constante de leads pero no tienen un equipo dedicado a buscarlos', metric: 'las empresas que responden en menos de cinco minutos convierten hasta veintiun veces mas. Asi de simple', question: 'como estan generando su pipeline de prospectos hoy?' };
  }
  if (/mining|mineria|oil|energy|gas/.test(ind)) {
    return { hook: 'tener un pipeline comercial predecible aunque los ciclos de venta sean largos', pain: 'en mineria los ciclos son largos y las relaciones son todo, pero eso no significa que la prospeccion tenga que ser manual', metric: 'el retorno que ven las empresas que automatizan esto es de casi cuatro veces lo que invierten, segun Forrester', question: 'tu equipo comercial tiene visibilidad clara de todo el pipeline o van caso a caso?' };
  }
  if (/telecom|comunicacion/.test(ind)) {
    return { hook: 'escalar las ventas sin tener que escalar el equipo', pain: 'en telecom la competencia es feroz y el que llega primero se lleva al cliente', metric: 'puedes hacer hasta cinco a siete veces mas conversiones que si intentaras armarlo tu mismo', question: 'cada lead que no contactas a tiempo, cuanto te esta costando?' };
  }
  return { hook: 'automatizar la parte de prospeccion para que tu equipo solo hable con gente que realmente quiere comprar', pain: 'la prospeccion manual le come tiempo a la gente que deberia estar cerrando ventas', metric: 'puedes hacer hasta cinco a siete veces mas conversiones que si intentaras armarlo tu mismo o le pagaras a alguien para hacerlo por ti', question: 'tu equipo de ventas pasa mas tiempo buscando prospectos o cerrando negocios?' };
}

const IND = lookupIndustry(lead.industry);

// ── EMAIL TEMPLATES ──────────────────────────────────────────
const TEMPLATES = {
  1: {
    subject: 'una idea para {company}',
    body: '{firstName}, te escribo porque estuve mirando lo que hacen en {company} y me quedo dando vueltas una idea.\n\n{personalHook}\n\nNosotros en Sisteco nos dedicamos a {industryHook}. En simple: nos encargamos de toda la prospeccion para que tu equipo solo hable con gente que ya quiere comprar.\n\nSi te tinca, te cuento como funciona en quince minutos. Sin compromiso.\n\nFelipe Martinez\nSisteco — Santiago, Chile'
  },
  2: {
    subject: 'algo que vi sobre {industryName}',
    body: '{firstName}, te comparto un dato que encontre y me parecio relevante para lo que hacen en {company}:\n\n{metric}.\n\n{pain} Pero no tiene por que ser asi.\n\nSi quieres ver como lo estamos resolviendo para empresas como la tuya, me dices y te muestro en quince minutos.\n\nFelipe'
  },
  3: {
    subject: 'como lo estan haciendo otras empresas en Chile',
    body: '{firstName}, te lo pongo asi:\n\nHay empresas B2B en Chile que ya automatizaron su prospeccion y {metric}. La diferencia es simple: responden rapido y solo le dedican tiempo a los leads que realmente van a comprar.\n\n{pain}. Pero cuando automatizas esa parte, tu equipo se libera para hacer lo que mejor sabe hacer: cerrar.\n\nQuince minutos para mostrarte como? Me dices un dia que te acomode.\n\nFelipe'
  },
  4: {
    subject: '{firstName}, te hago una pregunta',
    body: '{firstName}, te la hago corta: {directQuestion}\n\nSi es algo que les pasa, te muestro en quince minutos como lo estamos resolviendo. Si no, todo bien, no insisto mas.\n\nFelipe'
  },
  5: {
    subject: 'ultimo mensaje, {firstName}',
    body: '{firstName}, entiendo si no es el momento o si esto no les hace sentido. Cero drama.\n\nSolo te dejo el dato por si en algun momento les sirve: {metric}. En vez de intentar armarlo ustedes, contratanos a nosotros y listo.\n\nMucho exito con lo que estan haciendo en {company}. Quedo por aca si algun dia quieres conversar.\n\nFelipe'
  }
};

// ── PERSONAL HOOK via GEMINI (touch 1 only) ──────────────────
let personalHook = '';
if (currentTouch === 1) {
  const additionalInfo = (lead.additional_info || '').substring(0, 400);
  if (additionalInfo && config.geminiKey) {
    try {
      const prompt = 'Genera una observacion de 1-2 oraciones sobre ' + lead.first_name + ' de ' + lead.company + ' para un cold email B2B en Chile. Info de su LinkedIn: "' + additionalInfo + '". Cargo: ' + (lead.job_title || '') + '. Escribe en espanol chileno usando tuteo (tu, no usted). Maximo 40 palabras. No uses bullets, metricas con numeros, ni frases corporativas. Solo el texto del hook, sin comillas ni introductores.';
      const gRes = await fetch('https://generativelanguage.googleapis.com/v1beta/models/gemini-2.0-flash-lite:generateContent?key=' + config.geminiKey, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ contents: [{ parts: [{ text: prompt }] }] })
      });
      const gData = await gRes.json();
      const raw = (gData.candidates?.[0]?.content?.parts?.[0]?.text || '').trim();
      const sentences = raw.split(/(?<=[.!?])\s+/).filter(s => s.trim());
      personalHook = sentences.slice(0, 2).join(' ').trim();
      if (personalHook && !/[.!?]$/.test(personalHook)) personalHook += '.';
    } catch(e) {
      console.log('Gemini error:', e.message);
    }
  }
  if (!personalHook) {
    personalHook = 'Vi que tu equipo en ' + lead.company + ' esta activo justamente en el area donde Sisteco genera mas impacto.';
  }
}

// ── FILL TEMPLATE ─────────────────────────────────────────────
const tpl = TEMPLATES[currentTouch] || TEMPLATES[5];
const fill = s => s
  .replace(/{firstName}/g, lead.first_name || '')
  .replace(/{company}/g, lead.company || '')
  .replace(/{industryName}/g, lead.industry || 'tu industria')
  .replace(/{industryHook}/g, IND.hook)
  .replace(/{personalHook}/g, personalHook)
  .replace(/{metric}/g, IND.metric)
  .replace(/{pain}/g, IND.pain)
  .replace(/{directQuestion}/g, IND.question);

const subject = fill(tpl.subject);
const body = fill(tpl.body);

// ── NEXT TOUCH TIMING ─────────────────────────────────────────
const DELAYS = { 1: 3, 2: 4, 3: 5, 4: 7, 5: 0 };
const delayMs = (DELAYS[currentTouch] || 7) * 24 * 60 * 60 * 1000;
const nextSendAt = new Date(Date.now() + delayMs).toISOString();
const statusAfter = currentTouch >= 5 ? 'complete' : 'active';

return [{ json: {
  lead_email: lead.lead_email,
  first_name: lead.first_name,
  last_name: lead.last_name || '',
  company: lead.company,
  job_title: lead.job_title || '',
  industry: lead.industry || '',
  additional_info: lead.additional_info || '',
  linkedin_url: lead.linkedin_url || '',
  enqueued_at: lead.enqueued_at || '',
  subject,
  body,
  touch_sent: currentTouch,
  status_after: statusAfter,
  sent_at: new Date().toISOString(),
  next_send_at: nextSendAt
} }];

// Optional: notify Discord when touch 1 is sent (first contact with HOT lead)
const data = $input.first().json;
const config = $('Config').first().json;
if (data.touch_sent === 1 && config.discordWebhook) {
  try {
    await fetch(config.discordWebhook, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        content: '📧 **Secuencia iniciada** — ' + data.first_name + ' @ ' + data.company + '\nTouch: ' + data.touch_sent + ' | Asunto: "' + data.subject + '"\nEmail: ' + data.lead_email
      })
    });
  } catch(e) {
    console.log('Discord notify error:', e.message);
  }
}
return [{ json: { done: true, lead_email: data.lead_email, touch_sent: data.touch_sent, status_after: data.status_after } }];
